const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/file_versions',
  qs: {project_id: 'SOME_INTEGER_VALUE', file_id: 'SOME_INTEGER_VALUE'},
  headers: {
    Authorization: 'Bearer REPLACE_BEARER_TOKEN',
    'content-type': 'application/json'
  },
  body: {
    file_version: {
      name: 'my.pdf',
      notes: 'This file version is good',
      upload_uuid: '1QJ83Q56CVQR4X3C0JG7YV86F8'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/file_versions?project_id=SOME_INTEGER_VALUE&file_id=SOME_INTEGER_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
    Content = new StringContent("{\"file_version\":{\"name\":\"my.pdf\",\"notes\":\"This file version is good\",\"upload_uuid\":\"1QJ83Q56CVQR4X3C0JG7YV86F8\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

